import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int K = fs.nextInt();
        int C = fs.nextInt();

        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextInt();
        }

        int[] pref = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            pref[i] = pref[i - 1] + A[i - 1];
        }

        int total = pref[N];
        final int INF = 1_000_000_000;

        int ring = C + 1;
        int[][] dp = new int[ring][K + 1];
        for (int[] row : dp) {
            Arrays.fill(row, INF);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= N; i++) {
            int cur = i % ring;
            int prev = (i - 1) % ring;
            int maxJ = Math.min(K, i / C);

            dp[cur][0] = 0;

            if (i >= C) {
                int cover = pref[i] - pref[i - C];
                int old = (i - C) % ring;

                for (int j = 1; j <= maxJ; j++) {
                    int best = dp[prev][j];
                    int val = dp[old][j - 1] + cover;
                    if (val < best) {
                        best = val;
                    }
                    dp[cur][j] = best;
                }
            }

            if (maxJ < K) {
                dp[cur][maxJ + 1] = INF;
            }
        }

        int minCovered = dp[N % ring][K];
        System.out.println(total - minCovered);
    }
}
